// Keyed by string, not by SlotId: the PUBLIC doors are typed (that is where a
// typo must fail), while ScreenFrame composes its ids from a screen name and
// has nothing to assert against — and in an app with no slots at all SlotId is
// `never`, which no cast can produce.
const registry = new Map<string, ComponentType>();

export function registerSlots(slots: Partial<Record<SlotId, ComponentType>>): void {
  for (const [id, comp] of Object.entries(slots) as Array<[SlotId, ComponentType | undefined]>) {
    if (comp) registry.set(id, comp);
  }
}

export function getSlot(id: SlotId): ComponentType | undefined {
  return registry.get(id);
}

/** The same lookup for generated code that builds an id from a screen name. */
export function getSlotByName(id: string): ComponentType | undefined {
  return registry.get(id);
}

